function load(){try{const v=JSON.parse(localStorage.getItem('haven-city'));if(v&&v.tiles?.length){s={...defaultState(),...v};}}catch{} initMap();if(s.tiles.length){for(const t of s.tiles){let q=tileData[t.y*W+t.x];if(q)q.type=t.type;}s.buildings=s.buildings||[];for(const b of s.buildings){if(tileData[b.y*W+b.x])tileData[b.y*W+b.x].building=b;}}else{ // A small ready-to-play riverside starter settlement
const starter=[['road',19,17],['road',20,17],['road',21,17],['res',18,16],['res',20,16],['shop',22,16],['wind',18,19],['pump',22,19],['park',20,19]];for(const [id,x,y]of starter){let b={id:crypto.randomUUID?.()||String(Math.random()),type:id,x,y,level:1,develop:0,issue:null};s.buildings.push(b);tileData[y*W+x].building=b;}}
 camera.x=canvas.clientWidth/2-20*TILE;camera.y=canvas.clientHeight/2-17*TILE;}
function save(){s.tiles=tileData.filter(t=>t.type!=='grass'||t.building).map(({x,y,type})=>({x,y,type}));try{localStorage.setItem('haven-city',JSON.stringify(s));}catch{}const el=document.getElementById('saveFlash');el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1300);}
function rank(){return s.pop>=20000?'Metropolis':s.pop>=6000?'City':s.pop>=1800?'Town':'Village'}
function unlock(id){let tier=rank();return !(['mall','school','transit','monument'].includes(id)&&tier==='Village')&&!(['tech','university','stadium'].includes(id)&&['Village','Town'].includes(tier))&&!(id==='nuclear'&&tier!=='Metropolis')&&!(id==='wonder'&&tier!=='Metropolis')}
function renderCategories(){const host=document.getElementById('categories');host.innerHTML=categories.map(([id,icon,label])=>`<button class="category ${id===s.category?'active':''}" data-cat="${id}"><i>${icon}</i>${label}</button>`).join('');host.querySelectorAll('button').forEach(b=>b.onclick=()=>{s.category=b.dataset.cat;if(s.category==='bulldoze')s.selected='bulldoze';else if(s.selected==='bulldoze'||!items.some(i=>i.id===s.selected&&i.cat===s.category))s.selected=items.find(i=>i.cat===s.category&&unlock(i.id))?.id;renderCategories();renderItems();});}
function renderItems(){const host=document.getElementById('buildList');const list=items.filter(i=>i.cat===s.category&&unlock(i.id));if(s.category==='bulldoze'){host.innerHTML='<button class="build-card active"><span class="emoji">🚜</span><strong>Bulldozer</strong><small>Clear tiles · 50% refund</small></button>';return;}host.innerHTML=list.map(i=>`<button class="build-card ${s.selected===i.id?'active':''}" data-id="${i.id}" title="${i.desc}"><span class="emoji">${i.icon}</span><strong>${i.name}</strong><small><span class="cost">${money(i.cost)}</span> · ${i.upkeep?money(i.upkeep)+'/min upkeep':'no upkeep'}</small></button>`).join('');host.querySelectorAll('button').forEach(b=>b.onclick=()=>{s.selected=b.dataset.id;s.selectedBuilding=null;document.getElementById('selection').classList.remove('show');renderItems();});}
function buildSliders(){let tax=document.getElementById('taxSliders');tax.innerHTML=[['res','Residential'],['com','Commercial'],['ind','Industrial']].map(([k,n])=>slider(`tax-${k}`,n,'Tax rate · higher taxes can slow growth',s.taxes[k],0,20,'%')).join('');let funds=document.getElementById('fundSliders');funds.innerHTML=Object.entries({power:'Power grid',water:'Water & sanitation',police:'Police',fire:'Fire & rescue',health:'Health',education:'Education',parks:'Parks & culture',waste:'Waste management'}).map(([k,n])=>slider(`fund-${k}`,n,'Service funding level',s.funds[k],0,150,'%')).join('');document.querySelectorAll('.slider-row input').forEach(el=>el.oninput=()=>{let [type,key]=el.id.split('-');s[type==='tax'?'taxes':'funds'][key]=+el.value;el.nextElementSibling.textContent=el.value+'%';if(type==='tax')updateUI();});}
function slider(id,name,detail,val,min,max,unit){return `<div class="slider-row"><label>${name}<small>${detail}</small></label><input id="${id}" type="range" min="${min}" max="${max}" value="${val}"><output>${val}${unit}</output></div>`;}
function buildPolicies(){document.getElementById('policyGrid').innerHTML=policyDefs.map(p=>`<label class="policy"><input type="checkbox" data-policy="${p.id}" ${s.policies[p.id]?'checked':''}><span><strong>${p.name}</strong><small>${p.desc}</small></span></label>`).join('');document.querySelectorAll('[data-policy]').forEach(e=>e.onchange=()=>{s.policies[e.dataset.policy]=e.checked;updateUI();});}
function setTab(tab){document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));document.querySelectorAll('.pane').forEach(p=>p.classList.toggle('active',p.id==='pane-'+tab));if(tab==='stats')renderStats();}
function renderStats(){let boxes=[['Population',fmt(s.pop)],['Treasury',money(s.cash)],['Happiness',Math.round(s.happiness)+'%'],['Crime',Math.round(s.crime)+'%'],['Pollution',Math.round(s.pollution)],['Milestone',rank()],['Developed lots',s.buildings.filter(b=>b.level>1).length],['City land',`${s.buildings.length} lots`],['Day',s.day]];document.getElementById('statsGrid').innerHTML=boxes.map(([l,v])=>`<div class="statbox"><label>${l}</label><b>${v}</b></div>`).join('');document.getElementById('journal').innerHTML=`Current milestone: <b style="color:var(--lime)">${rank()}</b><br>Next unlock: ${s.pop<1800?'Town at 1,800 residents':s.pop<6000?'City at 6,000 residents':s.pop<20000?'Metropolis at 20,000 residents':'All milestones reached'}<br>Residents are happiest when homes have road access, utilities, parks, and city services.`;}

function metrics(){const b=s.buildings;let res=b.filter(x=>['res','resmid','reshigh'].includes(x.type));let com=b.filter(x=>['shop','office','mall'].includes(x.type));let ind=b.filter(x=>['farm','factory','tech'].includes(x.type));let power=b.filter(x=>['wind','solar','coal','nuclear'].includes(x.type)).reduce((a,x)=>a+({wind:100,solar:160,coal:340,nuclear:900}[x.type]),0);let water=b.filter(x=>['pump','tower','treatment'].includes(x.type)).reduce((a,x)=>a+({pump:180,tower:220,treatment:380}[x.type]),0);let demand=s.pop*.08+b.filter(x=>x.type==='factory'||x.type==='tech').length*20;let wdemand=s.pop*.07;let powered=power*Math.min(1,s.funds.power/100),watered=water*Math.min(1,s.funds.water/100);s.powerUse=Math.min(100,Math.round(powered?demand/powered*100:0));s.waterUse=Math.min(100,Math.round(watered?wdemand/watered*100:0));let parks=b.filter(x=>x.type==='park').length,police=b.filter(x=>x.type==='police').length,fire=b.filter(x=>x.type==='fire').length,health=b.filter(x=>x.type==='hospital').length;let services=b.filter(x=>['school','university'].includes(x.type)).length;s.pollution=Math.max(0,8+ind.length*4+b.filter(x=>x.type==='coal').length*18-(s.policies.green?18:0)-b.filter(x=>x.type==='landfill').length*2);s.crime=Math.max(0,Math.min(95,18-police*12+(s.pop/3000)-(s.funds.police-100)*.08));s.happiness=Math.max(5,Math.min(99,66+parks*3+health*2+services*1.3+(s.policies.transit?8:0)+(s.policies.green?5:0)+(s.policies.festival?10:0)-(s.pollution*.45)-(s.crime*.25)-(s.powerUse>90?12:0)-(s.waterUse>90?12:0)-(s.taxes.res-8)*1.3-(s.policies.night?3:0)));
let taxIncome=(res.length*s.pop/(Math.max(res.length,1))*s.taxes.res*.14+com.length*s.taxes.com*5+ind.length*s.taxes.ind*5)*(1+(s.policies.subsidies?.25:0))*(s.policies.night?1.18:1);let expense=b.reduce((a,x)=>a+x.upkeep,0)+Object.values(s.funds).reduce((a,v)=>a+v*.025,0)+policyDefs.reduce((a,p)=>a+(s.policies[p.id]?p.upkeep:0),0);let income=taxIncome-expense;return{res,com,ind,power,water,income,expense,parks};}
function updateUI(){const m=metrics();document.getElementById('population').textContent=fmt(s.pop);document.getElementById('cash').textContent=money(s.cash);let inc=document.getElementById('income');inc.textContent=(m.income>=0?'+':'')+money(m.income);inc.className=m.income>=0?'good':'bad';document.getElementById('happiness').textContent=Math.round(s.happiness)+'%';document.getElementById('power').textContent=`${Math.round(m.power*s.funds.power/100)} / ${Math.round(s.pop*.08)}`;document.getElementById('water').textContent=`${Math.round(m.water*s.funds.water/100)} / ${Math.round(s.pop*.07)}`;let p=document.getElementById('pollution');p.textContent=Math.round(s.pollution);p.className=s.pollution>55?'bad':s.pollution>25?'warn':'good';let c=document.getElementById('crime');c.textContent=Math.round(s.crime)+'%';c.className=s.crime>30?'bad':s.crime>15?'warn':'good';document.getElementById('rank').textContent=`${rank()} · Year ${Math.ceil(s.day/30)}`;document.getElementById('clock').textContent=`${String(Math.floor(s.minute/60)%24).padStart(2,'0')}:${String(s.minute%60).padStart(2,'0')}`;document.getElementById('dayLabel').textContent=`${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][(s.day-1)%7]} · Day ${s.day}`;document.getElementById('news').textContent=newsItems[newsItems.length-1];}
function connectedRoad(x,y){return s.buildings.some(b=>['road','dirt','highway'].includes(b.type)&&Math.abs(b.x-x)+Math.abs(b.y-y)<=2);}
function nearType(b,types,r=6){return s.buildings.some(x=>types.includes(x.type)&&Math.hypot(x.x-b.x,x.y-b.y)<=r);}
function draw(){const dpr=Math.min(devicePixelRatio||1,2),w=canvas.clientWidth,h=canvas.clientHeight;if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);ctx.save();ctx.translate(camera.x,camera.y);ctx.scale(camera.zoom,camera.zoom);let x0=Math.max(0,Math.floor(-camera.x/(TILE*camera.zoom))-1),y0=Math.max(0,Math.floor(-camera.y/(TILE*camera.zoom))-1),x1=Math.min(W,Math.ceil((w-camera.x)/(TILE*camera.zoom))+1),y1=Math.min(H,Math.ceil((h-camera.y)/(TILE*camera.zoom))+1);let night=(s.minute<360||s.minute>1170),alpha=night?.34:0;
for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){let t=tileData[y*W+x],px=x*TILE,py=y*TILE;ctx.fillStyle=t.type==='water'?'#5595a0':t.type==='hill'?'#92ac75':t.type==='forest'?'#5c986e':((x+y)%2?'#85b679':'#8cbe7c');ctx.fillRect(px,py,TILE,TILE);if(t.type==='water'){ctx.fillStyle='#a1d2c37a';ctx.fillRect(px+8,py+13,22,2);ctx.fillRect(px+25,py+33,16,2);}else if(t.type==='forest'){ctx.fillStyle='#347b58';ctx.beginPath();ctx.arc(px+24,py+23,12,0,7);ctx.fill();ctx.fillStyle='#72af70';ctx.beginPath();ctx.arc(px+19,py+18,5,0,7);ctx.fill();}else if(t.type==='hill'){ctx.fillStyle='#afc992';ctx.beginPath();ctx.moveTo(px+4,py+38);ctx.lineTo(px+25,py+8);ctx.lineTo(px+44,py+38);ctx.fill();}
ctx.strokeStyle='#ffffff12';ctx.lineWidth=1;ctx.strokeRect(px,py,TILE,TILE);if(t.building)drawBuilding(t.building,px,py,night);}
if(alpha){ctx.fillStyle=`rgba(14,24,44,${alpha})`;ctx.fillRect(x0*TILE,y0*TILE,(x1-x0)*TILE,(y1-y0)*TILE);for(let b of s.buildings){if(b.x<x0||b.x>x1||b.y<y0||b.y>y1)continue;if(['res','resmid','reshigh','shop','office','mall','factory','tech','school','hospital'].includes(b.type)){ctx.fillStyle='#ffd474';ctx.beginPath();ctx.arc(b.x*TILE+TILE*.7,b.y*TILE+TILE*.38,2.1,0,7);ctx.fill();}}}
if(s.fire){ctx.fillStyle='#ff614a';ctx.beginPath();ctx.arc(s.fire.x*TILE+24,s.fire.y*TILE+17,9+Math.sin(performance.now()/90)*3,0,7);ctx.fill();ctx.fillStyle='white';ctx.font='16px sans-serif';ctx.fillText('!',s.fire.x*TILE+20,s.fire.y*TILE+21);}ctx.restore();requestAnimationFrame(draw);}
function drawBuilding(b,x,y,night){let type=b.type,road=['road','dirt','highway'].includes(type);if(road){ctx.fillStyle=type==='dirt'?'#b39a70':type==='highway'?'#424e50':'#596568';ctx.fillRect(x+2,y+2,TILE-4,TILE-4);ctx.strokeStyle='#e7e1b976';ctx.setLineDash([6,6]);ctx.beginPath();ctx.moveTo(x+2,y+24);ctx.lineTo(x+46,y+24);ctx.stroke();ctx.setLineDash([]);return;}
let colors={res:'#e9d8a9',resmid:'#d5b982',reshigh:'#bdc9ce',shop:'#e7a96f',office:'#85bcc0',mall:'#d5a2bd',farm:'#9dca78',factory:'#a5aaa3',tech:'#9bb4dc',wind:'#f1f0df',solar:'#e5c765',coal:'#8e9890',nuclear:'#bd81a2',pump:'#7cc3d0',tower:'#71b5cf',treatment:'#6ca69d',landfill:'#9caa78',park:'#83be7c',police:'#8aa9d0',fire:'#df8973',hospital:'#f1e4dc',school:'#e6c982',university:'#b5aad4',transit:'#76c4ba',monument:'#e9c67f',stadium:'#cfb17d',wonder:'#dcad72'};let tall=['resmid','reshigh','office','tech','hospital','university','wonder'].includes(type);let bw=tall?31:37,bh=tall?36:28,baseX=x+(TILE-bw)/2,baseY=y+TILE-bh-4;ctx.fillStyle='#263a33';ctx.fillRect(baseX+2,baseY+3,bw,bh);ctx.fillStyle=colors[type]||'#ddd';ctx.fillRect(baseX,baseY,bw,bh);ctx.fillStyle='#ffffff55';ctx.fillRect(baseX,baseY,bw,4);
ctx.fillStyle=night?'#ffe39a':'#6d8b8c';for(let wx=baseX+6;wx<baseX+bw-4;wx+=9)for(let wy=baseY+9;wy<baseY+bh-4;wy+=9)ctx.fillRect(wx,wy,4,5);
ctx.font='14px sans-serif';ctx.textAlign='center';ctx.fillText(({res:'⌂',resmid:'▥',reshigh:'▥',shop:'▣',office:'▤',mall:'▤',farm:'♧',factory:'⚙',tech:'⌘',wind:'♧',solar:'☼',coal:'⌁',nuclear:'☢',pump:'◉',tower:'♧',treatment:'♻',landfill:'♻',park:'♣',police:'✦',fire:'✹',hospital:'✚',school:'▰',university:'✧',transit:'↗',monument:'◈',stadium:'◇',wonder:'✧'})[type]||'·'),x+24,baseY-3);
if(b.level>1){ctx.fillStyle='#fff4a8';ctx.fillRect(x+34,y+6,10,10);ctx.fillStyle='#26372f';ctx.font='bold 8px sans-serif';ctx.fillText('↑',x+39,y+14);}let issue=b.issue;if(issue){ctx.fillStyle='#ff675d';ctx.beginPath();ctx.arc(x+41,y+8,8,0,7);ctx.fill();ctx.fillStyle='#fff';ctx.font='bold 10px sans-serif';ctx.fillText(issue,x+41,y+12);} }

function screenToTile(clientX,clientY){let r=canvas.getBoundingClientRect();return{x:Math.floor((clientX-r.left-camera.x)/(TILE*camera.zoom)),y:Math.floor((clientY-r.top-camera.y)/(TILE*camera.zoom))};}
function place(x,y){if(x<0||x>=W||y<0||y>=H)return;let t=tileData[y*W+x],b=t.building;if(s.selected==='bulldoze'){if(b){s.cash+=Math.floor((items.find(i=>i.id===b.type)?.cost||0)*.5);s.buildings=s.buildings.filter(v=>v!==b);t.building=null;notify(`Cleared ${b.type}; half the construction cost refunded.`);updateUI();}return;}let it=items.find(i=>i.id===s.selected);if(!it)return;if(b){selectBuilding(b);return;}if(t.type==='water'||t.type==='hill'){newsItems.push(t.type==='water'?'Water and steep hills cannot be built on.':'The hillside is too steep for construction.');updateUI();return;}if(t.type==='forest'&&!['park','farm'].includes(it.id)){newsItems.push('Clear trees with the bulldozer before building here.');updateUI();return;}if(s.cash<it.cost){notify('Treasury too low','Wait for tax revenue or adjust your budget.');return;}if(!['road','dirt','highway'].includes(it.id)&&!connectedRoad(x,y)){notify('Road access needed','Connect this lot to a road first.');return;}s.cash-=it.cost;let nb={id:crypto.randomUUID?.()||`${Date.now()}${Math.random()}`,type:it.id,x,y,level:1,develop:0,issue:null,upkeep:it.upkeep};t.building=nb;s.buildings.push(nb);t.type='grass';document.getElementById('selection').classList.remove('show');updateUI();}
function selectBuilding(b){s.selectedBuilding=b.id;let box=document.getElementById('selection');box.classList.add('show');let label=items.find(i=>i.id===b.type)?.name||b.type;let issue=b.issue?`<span style="color:var(--red)">⚠ ${issueText(b.issue)}</span>`:'<span style="color:var(--lime)">✓ Operating normally</span>';box.innerHTML=`<button class="toast-x" id="closeSelection">×</button><h3>${label} ${b.level>1?'· Level '+b.level:''}</h3><p>${issue}</p><p>${roadName(b)} · ${b.upkeep?money(b.upkeep)+'/min upkeep':'No upkeep'}</p><p>${b.type==='res'?`Residents: ${b.level*120}`:''}</p><button id="demolish">Demolish · ${money(Math.floor((items.find(i=>i.id===b.type)?.cost||0)*.5))} refund</button>`;document.getElementById('closeSelection').onclick=()=>box.classList.remove('show');document.getElementById('demolish').onclick=()=>{s.selected='bulldoze';s.category='bulldoze';renderCategories();renderItems();box.classList.remove('show');};}
function roadName(b){return connectedRoad(b.x,b.y)?'Road access connected':'No nearby road connection';}
function issueText(code){return({P:'No power',W:'No water',R:'No road access',F:'Fire emergency',T:'Trash buildup'})[code]||code;}
let elapsed=0,simSecond=0;
function sim(dt){if(!s.speed)return;elapsed+=dt*s.speed;simSecond+=dt*s.speed;while(simSecond>=1){simSecond--;s.minute++;if(s.minute>=1440){s.minute=0;s.day++;daily();}if(s.minute%5===0)tickCity();if(s.minute%60===0)updateUI();if(s.minute%30===0)saveTick++;}if(elapsed>7){elapsed=0;updateUI();}}
function tickCity(){let m=metrics(),newPop=0;for(let b of s.buildings){if(['res','resmid','reshigh','shop','office','mall','farm','factory','tech'].includes(b.type)){let power=m.power*s.funds.power/100>=s.pop*.08,water=m.water*s.funds.water/100>=s.pop*.07,road=connectedRoad(b.x,b.y);b.issue=!road?'R':!power?'P':!water?'W':null;let growth=(road&&power&&water?1:.18)*(s.happiness/75);b.develop+=growth;if(b.develop>35&&b.level<4){b.level++;b.develop=0;if(['res','resmid','reshigh'].includes(b.type))newPop+=b.level*22;else newPop+=3;newsItems.push(`${items.find(i=>i.id===b.type)?.name||'A district'} is growing. More jobs and neighbors are arriving!`);}if(['res','resmid','reshigh'].includes(b.type))newPop+=Math.max(0,(b.level*1.1)*(s.happiness/80));}}
 s.pop=Math.max(0,s.pop+newPop);if(s.fire&&rand()<.015){let target=s.buildings.find(b=>b.x===s.fire.x&&b.y===s.fire.y);if(target){target.issue=null;target.level=Math.max(1,target.level-1);}s.fire=null;document.getElementById('eventToast').classList.remove('show');newsItems.push('Fire crews contained a blaze before it could spread.');}
 if(s.minute%45===0)maybeEvent();if(s.pop>=1800&&s.lastMilestone<1)milestone(1,'Town','Mid-rise districts, schools, public transit and the riverfront pavilion are now available.');if(s.pop>=6000&&s.lastMilestone<2)milestone(2,'City','Tech campuses, universities and the grand stadium are unlocked.');if(s.pop>=20000&&s.lastMilestone<3)milestone(3,'Metropolis','Nuclear power and the Skyline Spire are now available.');}
function daily(){let m=metrics();s.cash+=m.income*60;let growth=s.happiness>60?Math.max(0,Math.round(s.pop*.003*(s.powerUse<100&&s.waterUse<100?1:.25))):0;s.pop+=growth;if(s.cash<0){s.happiness=Math.max(15,s.happiness-3);newsItems.push('The treasury is in deficit. Adjust taxes or service funding.');}if(s.day%7===0)newsItems.push(`Week ${Math.ceil(s.day/7)} report: ${fmt(s.pop)} residents call Haven home.`);}
function notify(text,sub=''){newsItems.push(text);let title=document.getElementById('eventTitle'),msg=document.getElementById('eventText'),toast=document.getElementById('eventToast');title.textContent='Mayor alert';msg.textContent=sub||text;document.getElementById('eventAction').textContent='Got it';document.getElementById('eventAction').onclick=()=>toast.classList.remove('show');toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),4200);updateUI();}
function milestone(num,name,desc){s.lastMilestone=num;document.getElementById('eventTitle').textContent=`Milestone reached · ${name}`;document.getElementById('eventText').textContent=desc;document.getElementById('eventAction').textContent='Celebrate';document.getElementById('eventAction').onclick=()=>document.getElementById('eventToast').classList.remove('show');document.getElementById('eventToast').classList.add('show');newsItems.push(`Haven has grown into a ${name}! New options have been unlocked.`);renderItems();}
function maybeEvent(){let options=['festival','boom','outage','traffic','fire'],type=options[Math.floor(rand()*options.length)];if(type==='festival'){s.happiness=Math.min(99,s.happiness+4);newsItems.push('🎉 A spontaneous neighborhood festival brings the city together!');notify('Neighborhood festival','A joyful festival is lifting spirits across Haven.');}else if(type==='boom'){s.cash+=350;newsItems.push('📈 A regional business boom brought a surprise $350 to the treasury.');notify('Economic boom','Regional investors contributed $350.');}else if(type==='outage'){let targets=s.buildings.filter(b=>['res','shop','factory','office'].includes(b.type));if(targets.length){let b=targets[Math.floor(rand()*targets.length)];b.issue='P';setTimeout(()=>{if(b.issue==='P')b.issue=null;},12000);newsItems.push('⚡ A brief grid outage is disrupting a neighborhood.');notify('Power outage','Grid crews are responding. Review power capacity and funding.');}}else if(type==='traffic'){let residents=s.buildings.filter(b=>['res','resmid','reshigh'].includes(b.type));if(residents.length){let b=residents[Math.floor(rand()*residents.length)];b.issue='R';setTimeout(()=>{if(b.issue==='R')b.issue=null;},15000);}newsItems.push('🚗 Citizens report a traffic jam near a busy district.');notify('Traffic jam','A road upgrade or free transit ordinance can ease congestion.');}else{let candidates=s.buildings.filter(b=>['res','resmid','factory','shop'].includes(b.type));if(candidates.length&&!s.fire){let b=candidates[Math.floor(rand()*candidates.length)];s.fire={x:b.x,y:b.y};b.issue='F';document.getElementById('eventTitle').textContent='🚨 Fire reported';document.getElementById('eventText').textContent='A fire is spreading! Dispatch the fire department or pay $120 for an emergency crew.';let btn=document.getElementById('eventAction');btn.textContent='Dispatch crew · $120';btn.onclick=()=>{if(s.cash>=120){s.cash-=120;s.fire=null;let target=s.buildings.find(v=>v.x===b.x&&v.y===b.y);if(target)target.issue=null;document.getElementById('eventToast').classList.remove('show');newsItems.push('Emergency crews contained the fire.');}else notify('Insufficient funds','The emergency crew costs $120.');};document.getElementById('eventToast').classList.add('show');newsItems.push('🚨 Fire reported! Tap the alert to dispatch an emergency crew.');}}}

