function put(type,x,y,free=false){if(x<0||y<0||x>=W||y>=H)return false;let q=map[y*W+x],item=items.find(i=>i.id===type);if(!item)return false;if(q.building){if(type==='bulldoze'){let b=q.building,refund=Math.floor((items.find(i=>i.id===b.type)?.cost||0)*.5);s.cash+=refund;s.buildings=s.buildings.filter(v=>v!==b);q.building=null;document.getElementById('selection').classList.remove('show');addNews(`${b.type} cleared; ${money(refund)} returned to the treasury.`);updateUI();return true}return false}if(q.type==='water'||q.type==='hill')return false;if(!free&&s.cash<item.cost){toast('Treasury low',`You need ${money(item.cost)} to build ${item.name}.`,'Dismiss');return false}if(!['road','dirt','highway'].includes(type)&&!connected(x,y)){toast('Road access needed','Place this building beside a road first.','Got it');return false}if(!free)s.cash-=item.cost;let b={type,x,y,level:1,issue:null};q.building=b;s.buildings.push(b);updateUI();return true}
function addNews(text){news.push(text);if(news.length>8)news.shift();document.getElementById('news').textContent=text}
function toast(title,text,action='OK'){document.getElementById('eventTitle').textContent=title;document.getElementById('eventText').textContent=text;document.getElementById('eventAction').textContent=action;document.getElementById('eventToast').classList.add('show')}
function selectTile(x,y){if(x<0||y<0||x>=W||y>=H)return;let b=map[y*W+x].building;if(!b){document.getElementById('selection').classList.remove('show');return}let item=items.find(i=>i.id===b.type);let el=document.getElementById('selection');el.innerHTML=`<h3>${item?.icon||'🏗️'} ${item?.name||b.type} ${b.level>1?'· Level '+b.level:''}</h3><p>Lot ${x+1}, ${y+1} · ${item?.upkeep?money(item.upkeep)+'/min upkeep':'No upkeep'}</p><p>${item?.desc||''}${b.issue?`<br><b class="bad">Issue: ${b.issue}</b>`:''}</p>${['res','resmid','reshigh'].includes(b.type)?'<p>Residential capacity · growth follows demand and city services.</p>':''}<button id="demolish">Demolish · 50% refund</button>`;el.classList.add('show');document.getElementById('demolish').onclick=()=>put('bulldoze',x,y)}
function pointerDown(e){if(e.button!==undefined&&e.button!==0)return;canvas.setPointerCapture?.(e.pointerId);pointer={id:e.pointerId,x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY,moved:false};}
function pointerMove(e){if(!pointer||pointer.id!==e.pointerId)return;let dx=e.clientX-pointer.lastX,dy=e.clientY-pointer.lastY;if(Math.abs(e.clientX-pointer.x)+Math.abs(e.clientY-pointer.y)>4)pointer.moved=true;if(pointer.moved){cam.x+=dx;cam.y+=dy}pointer.lastX=e.clientX;pointer.lastY=e.clientY}
function pointerUp(e){if(!pointer||pointer.id!==e.pointerId)return;let p=pointer;pointer=null;if(!p.moved){let t=screenTile(e.clientX,e.clientY);if(s.selected==='bulldoze')put('bulldoze',t.x,t.y);else if(s.selected)put(s.selected,t.x,t.y);selectTile(t.x,t.y)}}
function zoom(factor,cx=canvas.clientWidth/2,cy=canvas.clientHeight/2){let old=cam.zoom,next=Math.max(.55,Math.min(1.8,old*factor));cam.x=cx-(cx-cam.x)*next/old;cam.y=cy-(cy-cam.y)*next/old;cam.zoom=next}
