function makeStarter(){s=fresh();initMap();let start=[['road',17,17],['road',18,17],['road',19,17],['road',20,17],['res',17,16],['res',19,16],['shop',18,16],['farm',20,16],['park',17,18],['wind',22,17],['pump',21,18]];for(let [type,x,y]of start)put(type,x,y,true);s.cash=5000;s.pop=420;s.happiness=76;news=['Welcome to Haven! Your starter settlement is ready to grow.'];}
const capacity={res:420,resmid:900,reshigh:1800},events=[{title:'A festival in the square',text:'Residents are asking for a little celebration. Spend $250 to boost happiness, or let the request pass.',cost:250,benefit:'Happiness rises after a lively festival.'},{title:'A road repair grant',text:'The regional council offers $400 toward infrastructure. Accept the grant?',cost:0,benefit:'The grant has been added to the treasury.',grant:400},{title:'A dry spell',text:'Water use is rising in Haven. Invest $300 in conservation, or carry on as usual.',cost:300,benefit:'Conservation efforts eased pressure on water supplies.'}];
function simulate(){if(!s.speed)return;let beforeDay=s.day;s.minute+=s.speed;if(s.minute>=1440){s.minute-=1440;s.day++;}let m=calc();s.cash+=m.income*s.speed;let utility=(m.power*s.funds.power/100>=s.pop*.08)&&(m.water*s.funds.water/100>=s.pop*.07);if(s.minute%60<s.speed){let homes=s.buildings.filter(b=>capacity[b.type]),cap=homes.reduce((n,b)=>n+capacity[b.type]*(b.level>1?1.35:1),0),growth=cap>s.pop?Math.max(1,Math.round((cap-s.pop)*.012*(s.happiness/70)*(utility?1:.45))):0;if(s.happiness<28)growth=-Math.min(3,Math.ceil((28-s.happiness)/10));s.pop=Math.max(0,Math.min(cap,s.pop+growth));for(let b of homes)if(b.level<3&&s.pop>homes.reduce((n,v)=>n+capacity[v.type]*v.level,0)*.62)b.level++;if(s.cash<0&&s.minute%180<s.speed)addNews('Budget warning: Haven is running a deficit. Adjust taxes or service funding.');updateUI();if(s.pop>=1800&&s.lastMilestone<1){s.lastMilestone=1;addNews('Haven is now a Town! New buildings are available.');renderItems();}if(s.pop>=6000&&s.lastMilestone<2){s.lastMilestone=2;addNews('Haven is now a City! New districts and services unlocked.');renderItems();}if(s.pop>=20000&&s.lastMilestone<3){s.lastMilestone=3;addNews('Haven is now a Metropolis! All construction tiers unlocked.');renderItems();}if(s.day!==beforeDay){if(s.day%3===0)triggerEvent();save(false)}}}
function triggerEvent(){if(document.getElementById('eventToast').classList.contains('show'))return;let ev=events[Math.floor(rand()*events.length)];s.fire=null;document.getElementById('eventTitle').textContent=ev.title;document.getElementById('eventText').textContent=ev.text;document.getElementById('eventAction').textContent=ev.grant?'Accept':`Spend ${money(ev.cost)}`;document.getElementById('eventToast').dataset.event=String(events.indexOf(ev));document.getElementById('eventToast').classList.add('show');}
function bind(){canvas.addEventListener('pointerdown',pointerDown);canvas.addEventListener('pointermove',pointerMove);canvas.addEventListener('pointerup',pointerUp);canvas.addEventListener('pointercancel',()=>pointer=null);canvas.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY<0?1.1:.9,e.offsetX,e.offsetY)},{passive:false});document.getElementById('zoomIn').onclick=()=>zoom(1.15);document.getElementById('zoomOut').onclick=()=>zoom(.87);document.getElementById('centerMap').onclick=centerMap;document.getElementById('saveBtn').onclick=()=>save();document.getElementById('mayorBtn').onclick=document.getElementById('mobileMayor').onclick=()=>document.getElementById('mayorModal').classList.add('open');document.getElementById('closeMayor').onclick=()=>document.getElementById('mayorModal').classList.remove('open');document.getElementById('mayorModal').onclick=e=>{if(e.target.id==='mayorModal')e.currentTarget.classList.remove('open')};document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{document.querySelectorAll('.tab,.pane').forEach(n=>n.classList.remove('active'));t.classList.add('active');document.getElementById('pane-'+t.dataset.tab).classList.add('active');if(t.dataset.tab==='stats'){stats()}});document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>{s.speed=+b.dataset.speed;document.querySelectorAll('[data-speed]').forEach(v=>v.classList.toggle('active',+v.dataset.speed===s.speed))});document.getElementById('dismissEvent').onclick=()=>document.getElementById('eventToast').classList.remove('show');document.getElementById('eventAction').onclick=()=>{let box=document.getElementById('eventToast'),ev=events[+box.dataset.event];if(ev){if(ev.grant)s.cash+=ev.grant;else if(s.cash>=ev.cost){s.cash-=ev.cost;if(ev.title.includes('festival'))s.happiness=Math.min(99,s.happiness+7)}else addNews('Haven could not afford the requested event response.')}box.classList.remove('show');if(ev)addNews(ev.benefit);updateUI()};document.getElementById('news').onclick=()=>{document.getElementById('mayorModal').classList.add('open');document.querySelector('[data-tab="stats"]').click()};window.addEventListener('resize',()=>{if(!cam.x&&!cam.y)centerMap()});window.addEventListener('keydown',e=>{if(e.key==='Escape'){document.getElementById('mayorModal').classList.remove('open');document.getElementById('eventToast').classList.remove('show');document.getElementById('selection').classList.remove('show')}if(e.key===' '){e.preventDefault();s.speed=s.speed?0:1;document.querySelectorAll('[data-speed]').forEach(v=>v.classList.toggle('active',+v.dataset.speed===s.speed))}});}
function boot(){if(!load()){makeStarter();save(false)}else{initMap();for(let b of s.buildings)if(b.x>=0&&b.y>=0&&b.x<W&&b.y<H)map[b.y*W+b.x].building=b;}renderCategories();renderItems();buildBudget();buildPolicies();bind();centerMap();updateUI();setInterval(simulate,1000);setInterval(()=>save(false),15000);render();}
boot();
})();
</script></body></html>

