.bottom{z-index:4;background:#142126;border-top:1px solid var(--line);padding:10px 15px 9px;display:flex;gap:12px;align-items:stretch}

.build-side{display:flex;gap:5px;align-items:center;border-right:1px solid var(--line);padding-right:11px}

.category{height:72px;min-width:60px;padding:7px;border-radius:12px;background:transparent;color:var(--muted);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;font-size:10px}

.build-list{display:flex;gap:8px;overflow-x:auto;flex:1;align-items:center;scrollbar-width:thin}

.build-card{height:76px;min-width:130px;text-align:left;background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:9px 11px}

.ticker{width:220px;display:flex;flex-direction:column;justify-content:center;border-left:1px solid var(--line);padding-left:12px;overflow:hidden}

.event-toast{position:fixed;z-index:8;top:80px;left:50%;transform:translateX(-50%);background:#253a32;border:1px solid #849f4c;border-radius:15px;padding:13px 15px;display:none;width:min(400px,calc(100vw - 30px));box-shadow:0 10px 35px #0007}

